// The "Play Together" trailer: the online update, the DS games, the Monster
// Walker, the minigames and Zallax's Emerald 3DS Voxels. The beat sheet is
// tools/trailer/TRAILER_ONLINE.md; every time below matches a row there.
//
// Footage: public/footage (junction to G:\Gen2Recomped\trailer_footage).
// Audio:   public/audio, generated by tools/trailer/audio/make_audio.py
//          (original, procedural; git-ignored).
//
//   npx remotion studio src/index.ts
//   npx remotion render src/index.ts OnlineTrailer out/online_trailer.mp4 --crf 16
import React from "react";
import {
  AbsoluteFill,
  Audio,
  Easing,
  interpolate,
  OffthreadVideo,
  Sequence,
  spring,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { Card, GOLD, INK, Logo, PIXEL, SANS, useEdgeFade } from "./Trailer";

const FPS = 30;
const s = (sec: number) => Math.round(sec * FPS);

// set false to cut without sound (for example before make_audio.py has run)
const AUDIO = true;
const CYAN = "#5ee6ff";

// ----------------------------------------------------------- building blocks

// clips recorded 4:3 inside the 16:9 frame (the minigames: 1440 wide, 240 px
// bars each side) get a blurred, enlarged copy of themselves behind them
// instead of black bars
const PILLARBOXED = new Set(["minigame_pokeathlon", "minigame_musical", "minigame_contest", "minigame_slots"]);

const Shot: React.FC<{ src: string; dur: number; from?: number; push?: number; fade?: number }> = ({
  src,
  dur,
  from = 0,
  push = 0.04,
  fade = 6,
}) => {
  const f = useCurrentFrame();
  const opacity = useEdgeFade(dur, fade);
  const scale = interpolate(f, [0, dur], [1, 1 + push]);
  if (PILLARBOXED.has(src)) {
    return (
      <AbsoluteFill style={{ opacity, backgroundColor: "black", overflow: "hidden" }}>
        <OffthreadVideo
          src={staticFile(`footage/${src}.mp4`)}
          startFrom={from}
          muted
          style={{
            width: "100%",
            height: "100%",
            objectFit: "cover",
            transform: "scale(1.6)",
            filter: "blur(36px) brightness(0.55) saturate(1.3)",
          }}
        />
        <AbsoluteFill style={{ transform: `scale(${scale})` }}>
          <OffthreadVideo
            src={staticFile(`footage/${src}.mp4`)}
            startFrom={from}
            muted
            style={{
              width: "100%",
              height: "100%",
              clipPath: "inset(0 240px)",
              filter: "drop-shadow(0 0 40px rgba(0,0,0,0.8))",
            }}
          />
        </AbsoluteFill>
      </AbsoluteFill>
    );
  }
  return (
    <AbsoluteFill style={{ opacity, backgroundColor: "black" }}>
      <OffthreadVideo
        src={staticFile(`footage/${src}.mp4`)}
        startFrom={from}
        muted
        style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${scale})` }}
      />
    </AbsoluteFill>
  );
};

// back-to-back cuts: [clip, seconds, start frame in the clip]
const Cuts: React.FC<{ cuts: [string, number, number?][]; push?: number }> = ({ cuts, push = 0.03 }) => {
  let t = 0;
  return (
    <>
      {cuts.map(([src, sec, from], i) => {
        const start = t;
        const len = s(sec);
        t += len;
        return (
          <Sequence key={i} from={start} durationInFrames={len}>
            <Shot src={src} dur={len} from={from ?? 20} fade={4} push={push} />
          </Sequence>
        );
      })}
    </>
  );
};

const Caption: React.FC<{ text: string; sub?: string; dur: number; pos?: "low" | "mid" | "top"; accent?: string }> = ({
  text,
  sub,
  dur,
  pos = "low",
  accent = GOLD,
}) => {
  const f = useCurrentFrame();
  const { fps } = useVideoConfig();
  const enter = spring({ frame: f, fps, config: { damping: 200 } });
  const out = interpolate(f, [dur - 8, dur], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  return (
    <AbsoluteFill
      style={{
        justifyContent: pos === "low" ? "flex-end" : pos === "top" ? "flex-start" : "center",
        alignItems: "flex-start",
        padding: pos === "low" ? "0 0 110px 120px" : pos === "top" ? "150px 0 0 120px" : "0 0 0 120px",
        opacity: out,
      }}
    >
      <div
        style={{
          transform: `translateY(${(1 - enter) * 40}px)`,
          opacity: enter,
          background: "linear-gradient(90deg, rgba(11,15,26,0.85), rgba(11,15,26,0))",
          padding: "22px 140px 22px 28px",
          borderLeft: `8px solid ${accent}`,
        }}
      >
        <div style={{ fontFamily: PIXEL, fontSize: 46, color: "white", letterSpacing: 2, textShadow: "4px 4px 0 #000" }}>
          {text}
        </div>
        {sub ? (
          <div style={{ fontFamily: SANS, fontSize: 30, color: "#d6e0f5", marginTop: 14, fontWeight: 500 }}>{sub}</div>
        ) : null}
      </div>
    </AbsoluteFill>
  );
};

// top-right game tag, like the first trailer's GenTag
const GameTag: React.FC<{ top: string; game: string; dur: number }> = ({ top, game, dur }) => {
  const f = useCurrentFrame();
  const { fps } = useVideoConfig();
  const enter = spring({ frame: f, fps, config: { damping: 200 } });
  const out = interpolate(f, [dur - 8, dur], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  return (
    <AbsoluteFill style={{ alignItems: "flex-end", justifyContent: "flex-start", padding: "110px 110px 0 0", opacity: out }}>
      <div style={{ textAlign: "right", transform: `translateX(${(1 - enter) * 60}px)`, opacity: enter }}>
        <div style={{ fontFamily: PIXEL, fontSize: 28, color: GOLD, textShadow: "3px 3px 0 #000" }}>{top}</div>
        <div style={{ fontFamily: PIXEL, fontSize: 54, color: "white", marginTop: 12, textShadow: "5px 5px 0 #000" }}>{game}</div>
      </div>
    </AbsoluteFill>
  );
};

const Flash: React.FC<{ at?: number; color?: string; peak?: number }> = ({ at = 0, color = "white", peak = 0.85 }) => {
  const f = useCurrentFrame();
  const o = interpolate(f, [at - 2, at, at + 14], [0, peak, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });
  return <AbsoluteFill style={{ backgroundColor: color, opacity: o, pointerEvents: "none" }} />;
};

// a big word slammed over footage on the drop
const Stamp: React.FC<{ text: string; dur: number; color?: string }> = ({ text, dur, color = CYAN }) => {
  const f = useCurrentFrame();
  const { fps } = useVideoConfig();
  const pop = spring({ frame: f, fps, config: { damping: 9, stiffness: 180 } });
  const out = interpolate(f, [dur - 8, dur], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  return (
    <AbsoluteFill style={{ justifyContent: "center", alignItems: "center", opacity: out }}>
      <div
        style={{
          fontFamily: PIXEL,
          fontSize: 150,
          color: "white",
          letterSpacing: 10,
          transform: `scale(${2.2 - 1.2 * pop})`,
          textShadow: `0 0 40px ${color}, 10px 10px 0 #000`,
        }}
      >
        {text}
      </div>
    </AbsoluteFill>
  );
};

const Letterbox: React.FC = () => (
  <>
    <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 70, background: "black" }} />
    <div style={{ position: "absolute", bottom: 0, left: 0, right: 0, height: 70, background: "black" }} />
  </>
);

// ------------------------------------------------------------------ cards

function TitleCard({ dur, line, sub, accent = GOLD }: { dur: number; line: string; sub?: string; accent?: string }) {
  const f = useCurrentFrame();
  const { fps } = useVideoConfig();
  const p = spring({ frame: f - 2, fps, config: { damping: 14 } });
  const late = interpolate(f, [10, 22], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  return (
    <Card dur={dur}>
      <div
        style={{
          fontFamily: PIXEL,
          fontSize: 64,
          color: "white",
          textAlign: "center",
          lineHeight: 1.5,
          transform: `translateY(${(1 - p) * 40}px)`,
          opacity: p,
          textShadow: `6px 6px 0 #000, 0 0 30px ${accent}55`,
        }}
      >
        {line}
      </div>
      {sub ? (
        <div style={{ fontFamily: SANS, fontSize: 34, color: "#d6e0f5", marginTop: 40, opacity: late, fontWeight: 600 }}>
          {sub}
        </div>
      ) : null}
    </Card>
  );
}

function Available({ dur }: { dur: number }) {
  const f = useCurrentFrame();
  const { fps } = useVideoConfig();
  const games: [string, string][] = [
    ["PLATINUM", "#b8c4dc"],
    ["HEARTGOLD", "#e8b830"],
    ["SOULSILVER", "#c8d0e0"],
    ["BLACK", "#f0f0f0"],
    ["WHITE", "#f0f0f0"],
  ];
  return (
    <Card dur={dur}>
      <div style={{ fontFamily: PIXEL, fontSize: 52, color: GOLD, letterSpacing: 4, marginBottom: 64, textShadow: "6px 6px 0 #7a3b00" }}>
        NOW AVAILABLE IN THE APP
      </div>
      <div style={{ display: "flex", gap: 56 }}>
        {games.map(([g, c], i) => {
          const p = spring({ frame: f - 6 - i * 5, fps, config: { damping: 14 } });
          return (
            <div
              key={g}
              style={{
                fontFamily: PIXEL,
                fontSize: 40,
                color: c,
                opacity: p,
                transform: `translateY(${(1 - p) * 50}px)`,
                textShadow: "5px 5px 0 #000",
              }}
            >
              {g}
            </div>
          );
        })}
      </div>
      <div style={{ fontFamily: SANS, fontSize: 30, color: "#d6e0f5", marginTop: 60 }}>
        Import your own ROM and play. Sinnoh, Johto and Unova.
      </div>
    </Card>
  );
}

function EndCard({ dur }: { dur: number }) {
  const f = useCurrentFrame();
  const late = interpolate(f, [24, 44], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  return (
    <Card dur={dur} bg="black">
      <Flash peak={0.9} />
      <Logo width={900} />
      <div style={{ opacity: late, textAlign: "center" }}>
        <div style={{ fontFamily: SANS, fontSize: 27, color: "#e8eefc", marginTop: 44, fontWeight: 600 }}>
          Red · Blue · Yellow · Gold · Silver · Crystal · FireRed · LeafGreen · Emerald
        </div>
        <div style={{ fontFamily: SANS, fontSize: 27, color: "#e8eefc", marginTop: 10, fontWeight: 600 }}>
          Platinum · HeartGold · SoulSilver · Black · White
        </div>
        <div style={{ fontFamily: SANS, fontSize: 25, color: "#9aa7c7", marginTop: 18 }}>
          Windows · macOS · Linux · Steam Deck · Android · iOS · Switch · Xbox
        </div>
        <div style={{ fontFamily: PIXEL, fontSize: 28, color: CYAN, marginTop: 44 }}>ONLINE NOW</div>
        <div style={{ fontFamily: SANS, fontSize: 28, color: "#b9c6ff", marginTop: 30 }}>discord.gg/4VXnEnePT</div>
        <div style={{ fontFamily: SANS, fontSize: 24, color: "white", marginTop: 14 }}>
          Rip packs with us on Tilt Rips: <span style={{ color: GOLD }}>tiltrips.com/r/GEN2RECOMP</span>
        </div>
        <div style={{ fontFamily: SANS, fontSize: 18, color: "#6b7591", marginTop: 34 }}>
          Non-commercial fan project. No game files included; import your own legally obtained ROMs.
        </div>
      </div>
    </Card>
  );
}

