export const ONLINE_TRAILER_FRAMES = s(102);

export const OnlineTrailer: React.FC = () => {
  const f = useCurrentFrame();
  const musicVol = interpolate(f, [ONLINE_TRAILER_FRAMES - s(3), ONLINE_TRAILER_FRAMES], [0.72, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  return (
    <AbsoluteFill style={{ backgroundColor: INK }}>
      {beats.map((b, i) => (
        <Sequence key={i} from={s(b.at)} durationInFrames={s(b.len)}>
          {b.el}
        </Sequence>
      ))}
      {AUDIO ? (
        <>
          <Audio src={staticFile("audio/music.wav")} volume={musicVol} />
          {SFX.map(([name, at, vol], i) => (
            <Sequence key={`sfx${i}`} from={s(at)} durationInFrames={s(4)}>
              <Audio src={staticFile(`audio/${name}.wav`)} volume={vol} />
            </Sequence>
          ))}
        </>
      ) : null}
    </AbsoluteFill>
  );
};
